package br.com.admeclesial.interfaces.rest.pessoa;

import br.com.admeclesial.application.pessoa.*; import br.com.admeclesial.domain.pessoa.RelacionamentoPessoa; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/relacionamentos-pessoa") public class RelacionamentoPessoaRestController { final RelacionamentoPessoaApplicationService s; public RelacionamentoPessoaRestController(RelacionamentoPessoaApplicationService s){this.s=s;} @PostMapping public RelacionamentoPessoa criar(@Valid @RequestBody RelacionamentoPessoaRequest r){return s.criar(r);} @GetMapping public List<RelacionamentoPessoa> listar(){return s.listar();} @GetMapping("/{uuid}") public RelacionamentoPessoa buscar(@PathVariable UUID uuid){return s.buscar(uuid);} @GetMapping("/por-pessoa") public List<RelacionamentoPessoa> porPessoa(@RequestParam UUID pessoaUuid){return s.porPessoa(pessoaUuid);} @PutMapping("/{uuid}") public RelacionamentoPessoa atualizar(@PathVariable UUID uuid,@Valid @RequestBody RelacionamentoPessoaRequest r){return s.atualizar(uuid,r);} @DeleteMapping("/{uuid}") public void remover(@PathVariable UUID uuid){s.remover(uuid);} }
